class Robot {
  constructor(name, battery) {
    this.name = name;
    this.battery = battery;
  }

  work(hours) {
    this.battery -= hours * 10;
  }

  get status() {
    return this.battery > 20 ? "ready" : "needs charging";
  }
}

const r1 = new Robot("Techno", 100);
const r2 = new Robot("Beep", 30);
r2.work(2);
console.log(r1.name, r1.status);
console.log(r2.name, r2.battery, r2.status);

class Ship {
  constructor(name) {
    this.name = name;
  }
  describe() {
    return `the ship ${this.name}`;
  }
}

class Explorer extends Ship {
  constructor(name, planet) {
    super(name);
    this.planet = planet;
  }
  describe() {
    return `${super.describe()}, target: ${this.planet}`;
  }
}

const e = new Explorer("Scout", "Mars");
console.log(e.describe());
console.log(e instanceof Ship);

