tasks.solution:
class FuelTank {
  constructor(capacity) {
    this.capacity = capacity;
    this.amount = capacity;
  }

  use(liters) {
    // if there's enough, subtract and return true, else false
    if (liters > this.amount) return false;
    this.amount -= liters;
    return true;
  }

  get percent() {
    // what percent is full?
    return Math.round((this.amount / this.capacity) * 100);
  }
}

const tank = new FuelTank(200);
tank.use(50);
console.log("Full: " + tank.percent + "%");

