challenge.solution:
class Astronaut {
  // static count
  static count = 0;

  constructor(name) {
    // increase the counter, id and name
    Astronaut.count += 1;
    this.id = Astronaut.count;
    this.name = name;
  }

  badge() {
    // #1 Ada
    return `#${this.id} ${this.name}`;
  }

  static fromList(names) {
    return names.map((name) => new Astronaut(name));
  }
}

const crew = Astronaut.fromList(["Ada", "Ben", "Eve"]);
crew.forEach((a) => console.log(a.badge()));

